if (polygon.empty()) {
        return CGAL::ON_UNBOUNDED_SIDE;
    }

    bool inside = false;
    size_t n = polygon.size();

    for (size_t i = 0; i < n; ++i) {
        const Point_2& p1 = polygon[i];
        const Point_2& p2 = polygon[(i + 1) % n];

        // Check if point is on the boundary (segment p1-p2)
        // A point is on the segment if it is collinear and within the bounding box of the segment
        if (CGAL::orientation(p1, p2, point) == CGAL::Collinear) {
            if (point.x() >= std::min(p1.x(), p2.x()) && point.x() <= std::max(p1.x(), p2.x()) &&
                point.y() >= std::min(p1.y(), p2.y()) && point.y() <= std::max(p1.y(), p2.y())) {
                return CGAL::ON_BOUNDARY;
            }
        }

        // Ray casting algorithm: cast a ray in the +X direction
        // Check if the segment p1-p2 crosses the horizontal ray emanating from 'point'
        if (((p1.y() > point.y()) != (p2.y() > point.y())) &&
            (point.x() < (p2.x() - p1.x()) * (point.y() - p1.y()) / (p2.y() - p1.y()) + p1.x())) {
            inside = !inside;
        }
    }

    return inside ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;

